selected.compute:
options = read('/input/options')
result = []
for combo in combinations(options, 2):
    ids = [combo[0]['id'], combo[1]['id']]
    if valid(ids):
        result = ids
        break
if result == []:
    for combo in combinations(options, 3):
        ids = [combo[0]['id'], combo[1]['id'], combo[2]['id']]
        if valid(ids):
            result = ids
            break
if result == []:
    for combo in combinations(options, 4):
        ids = [combo[0]['id'], combo[1]['id'], combo[2]['id'], combo[3]['id']]
        if valid(ids):
            result = ids
            break

selected.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
    if valid(selection):
        result = selection
    else:
        result = []
else:
    write('/output/selection', result)
if result != []:
    receipt_state = receipt('report')
    if receipt_state == 'success':
        pass
    elif receipt_state == 'unknown':
        delivery_state = status('report')
        if delivery_state == 'not_sent':
            send('report', 'team', result)
        elif delivery_state != 'sent':
            pass
    elif receipt_state == 'unattempted' or receipt_state == 'failure':
        send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
